using System.Globalization;

var ledger = new Ledger();
var inv = CultureInfo.InvariantCulture;
string Money(decimal x) => x.ToString("F2", inv);

string? line;
while ((line = Console.ReadLine()) != null)
{
    string[] words = line.Split(' ', StringSplitOptions.RemoveEmptyEntries);
    if (words.Length == 0) continue;
    string command = words[0].ToLowerInvariant();
    if (command == "quit") break;
    string[] parts = words[1..];
    foreach (string output in Handle(command, parts, words[0])) Console.WriteLine(output);
}
Console.WriteLine("Bye.");

IEnumerable<string> Handle(string command, string[] parts, string original)
{
    switch (command)
    {
        case "add":
        {
            if (parts.Length < 4) return ["Usage: add <date> <amount> <category> <description>"];
            if (!TryDate(parts[0], out var date)) return [$"Bad date: {parts[0]}"];
            if (!TryAmount(parts[1], out var amount) || amount == 0) return [$"Bad amount: {parts[1]}"];
            var t = ledger.Add(date, amount, parts[2], string.Join(" ", parts[3..]));
            return [$"Added #{t.Id}: {t.Date:yyyy-MM-dd} {t.Category} {Money(t.Amount)} {t.Description}"];
        }
        case "budget":
        {
            if (parts.Length != 2) return ["Usage: budget <category> <amount>"];
            if (!TryAmount(parts[1], out var amount) || amount <= 0) return [$"Bad amount: {parts[1]}"];
            ledger.SetBudget(parts[0], amount);
            return [$"Budget for {parts[0].ToLowerInvariant()}: {Money(amount)}"];
        }
        case "list":
        {
            var items = ledger.Transactions.AsEnumerable();
            if (parts.Length > 0)
            {
                if (!TryMonth(parts[0], out int y, out int m)) return [$"Bad month: {parts[0]}"];
                items = items.Where(t => t.Date.Year == y && t.Date.Month == m);
            }
            var lines = items.OrderBy(t => t.Date).ThenBy(t => t.Id)
                .Select(t => $"#{t.Id} {t.Date:yyyy-MM-dd} {t.Category,-10} {Money(t.Amount),9}  {t.Description}").ToList();
            return lines.Count == 0 ? ["No transactions."] : lines;
        }
        case "report":
        {
            if (parts.Length != 1) return ["Usage: report <month>"];
            if (!TryMonth(parts[0], out int y, out int m)) return [$"Bad month: {parts[0]}"];
            return Reports.Format(Reports.ForMonth(ledger, y, m), parts[0]);
        }
        case "undo":
            return [ledger.UndoLast() is Transaction removed ? $"Removed #{removed.Id}" : "Nothing to undo."];
        case "save":
            if (parts.Length != 1) return ["Usage: save <file>"];
            Storage.Save(ledger, parts[0]);
            return [$"Saved {ledger.Transactions.Count} transactions to {parts[0]}"];
        case "load":
        {
            if (parts.Length != 1) return ["Usage: load <file>"];
            var loaded = Storage.Load(parts[0]);
            if (loaded is null) return [$"Could not load {parts[0]}"];
            ledger = loaded;
            return [$"Loaded {ledger.Transactions.Count} transactions from {parts[0]}"];
        }
        default:
            return [$"Unknown command: {original}"];
    }
}

bool TryDate(string text, out DateOnly date) =>
    DateOnly.TryParseExact(text, "yyyy-MM-dd", inv, DateTimeStyles.None, out date);

bool TryAmount(string text, out decimal amount) =>
    decimal.TryParse(text, NumberStyles.AllowLeadingSign | NumberStyles.AllowDecimalPoint, inv, out amount)
    && amount == Math.Round(amount, 2);

bool TryMonth(string text, out int year, out int month)
{
    year = month = 0;
    if (!DateOnly.TryParseExact(text + "-01", "yyyy-MM-dd", inv, DateTimeStyles.None, out var d)) return false;
    (year, month) = (d.Year, d.Month);
    return true;
}

