public record Transaction(int Id, DateOnly Date, decimal Amount, string Category, string Description)
{
    public bool IsExpense => Amount < 0;
}

public class Ledger
{
    private readonly List<Transaction> _transactions = new();
    private readonly Dictionary<string, decimal> _budgets = new();
    private readonly Stack<int> _undo = new();

    public Ledger(int nextId = 1) => NextId = nextId;

    public int NextId { get; private set; }
    public IReadOnlyList<Transaction> Transactions => _transactions;
    public IReadOnlyDictionary<string, decimal> Budgets => _budgets;

    public Transaction Add(DateOnly date, decimal amount, string category, string description)
    {
        if (amount == 0) throw new ArgumentOutOfRangeException(nameof(amount), "must not be zero");
        var t = new Transaction(NextId++, date, amount, category.ToLowerInvariant(), description);
        _transactions.Add(t);
        _undo.Push(t.Id);
        return t;
    }

    public void Restore(Transaction t)
    {
        _transactions.Add(t);
        NextId = Math.Max(NextId, t.Id + 1);
    }

    public Transaction? UndoLast()
    {
        while (_undo.Count > 0)
        {
            int id = _undo.Pop();
            int index = _transactions.FindIndex(t => t.Id == id);
            if (index < 0) continue;
            var removed = _transactions[index];
            _transactions.RemoveAt(index);
            return removed;
        }
        return null;
    }

    public void SetBudget(string category, decimal monthly)
    {
        if (monthly <= 0) throw new ArgumentOutOfRangeException(nameof(monthly));
        _budgets[category.ToLowerInvariant()] = monthly;
    }

    public decimal? BudgetFor(string category) => _budgets.TryGetValue(category, out var b) ? b : null;
}

