using System.Globalization;

public record CategoryLine(string Category, decimal Spent, decimal? Budget)
{
    public bool Over => Budget is decimal b && Spent > b;
}

public record MonthReport(int Count, decimal Income, decimal Expenses, List<CategoryLine> Categories)
{
    public decimal Net => Income - Expenses;
}

public static class Reports
{
    public static MonthReport ForMonth(Ledger ledger, int year, int month)
    {
        var inMonth = ledger.Transactions.Where(t => t.Date.Year == year && t.Date.Month == month).ToList();
        var categories = inMonth.Where(t => t.IsExpense)
            .GroupBy(t => t.Category)
            .Select(g => new CategoryLine(g.Key, -g.Sum(t => t.Amount), ledger.BudgetFor(g.Key)))
            .OrderByDescending(c => c.Spent)
            .ThenBy(c => c.Category, StringComparer.Ordinal)
            .ToList();
        return new MonthReport(
            inMonth.Count,
            inMonth.Where(t => !t.IsExpense).Sum(t => t.Amount),
            -inMonth.Where(t => t.IsExpense).Sum(t => t.Amount),
            categories);
    }

    public static List<string> Format(MonthReport r, string month)
    {
        static string M(decimal x) => x.ToString("F2", CultureInfo.InvariantCulture);
        var lines = new List<string> { $"Report for {month}" };
        if (r.Count == 0)
        {
            lines.Add("No transactions.");
            return lines;
        }
        lines.Add($"{"Income:",-9}{M(r.Income),10}");
        lines.Add($"{"Expenses:",-9}{M(r.Expenses),10}");
        lines.Add($"{"Net:",-9}{M(r.Net),10}");
        if (r.Categories.Count > 0)
        {
            lines.Add("By category:");
            foreach (var c in r.Categories)
            {
                string budget = c.Budget is decimal b ? $" of {M(b)}{(c.Over ? " OVER" : "")}" : "";
                lines.Add($"  {c.Category,-10}{M(c.Spent),8}{budget}");
            }
        }
        return lines;
    }
}

