using System.Text.Json;

public static class Storage
{
    private sealed record SavedLedger(int Version, int NextId, List<Transaction> Transactions, Dictionary<string, decimal> Budgets);

    private static readonly JsonSerializerOptions Options = new() { PropertyNamingPolicy = JsonNamingPolicy.CamelCase };

    public static void Save(Ledger ledger, string path)
    {
        var data = new SavedLedger(1, ledger.NextId, ledger.Transactions.ToList(), ledger.Budgets.ToDictionary());
        File.WriteAllText(path, JsonSerializer.Serialize(data, Options));
    }

    public static Ledger? Load(string path)
    {
        try
        {
            var data = JsonSerializer.Deserialize<SavedLedger>(File.ReadAllText(path), Options);
            if (data is null || data.Version != 1 || data.Transactions is null) return null;
            var ledger = new Ledger(data.NextId);
            foreach (var t in data.Transactions) ledger.Restore(t);
            foreach (var (category, amount) in data.Budgets ?? new()) ledger.SetBudget(category, amount);
            return ledger;
        }
        catch (Exception e) when (e is IOException or JsonException or UnauthorizedAccessException or ArgumentException)
        {
            return null;
        }
    }
}
